/**
 * The Speaker for a provider, a key and a collaborator's settings.
 *
 * One place that knows every provider, so a route and the worker cannot build them
 * differently: a line regenerated by hand and the same line in a batch must be made alike.
 */
import "server-only";

import type { Preference } from "../preference";
import { elevenLabsSpeaker } from "./elevenlabs";
import { fishSpeaker } from "./fish";
import type { Provider, Speaker } from "./speaker";

/**
 * `relay` is for a line generated on its author's own machine (../relay.ts): the fetch every
 * provider request goes through, and the ElevenLabs voices that machine's account holds, which
 * this server cannot list without the key.
 */
export function speakerFrom(
  provider: Provider,
  apiKey: string,
  preference: Pick<Preference, "elevenlabs" | "fish">,
  relay?: { fetchImpl: typeof fetch; roster: ReadonlyMap<string, string> | null },
): Speaker {
  return provider === "fish"
    ? fishSpeaker({ apiKey, settings: preference.fish, fetchImpl: relay?.fetchImpl })
    : elevenLabsSpeaker({
        apiKey,
        settings: preference.elevenlabs,
        fetchImpl: relay?.fetchImpl,
        roster: relay?.roster ?? undefined,
      });
}
